-- composition of rule kernels L:extract_equijoin_predicate x P:aggregate_statistics (datafusion), template graft_exists
WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 5) SELECT '_'::text AS c0, (SELECT COUNT (*) FROM (SELECT * FROM t1 WHERE EXISTS (SELECT 1 FROM (SELECT '2000-01-01'::date AS c0 FROM (t4 AS a1 JOIN t4 AS a2 ON (a1.c0 = a2.c0)) GROUP BY a1.c0, a2.c0 UNION ALL (SELECT '2024-02-29'::date AS c0 UNION SELECT '1999-12-31'::date AS c0)) AS kb) OR NOT EXISTS (SELECT 1 FROM (SELECT '2000-01-01'::date AS c0 FROM (t4 AS a1 JOIN t4 AS a2 ON (a1.c0 = a2.c0)) GROUP BY a1.c0, a2.c0 UNION ALL (SELECT '2024-02-29'::date AS c0 UNION SELECT '1999-12-31'::date AS c0)) AS kb)) AS a2) AS c1, 0::bigint AS c2 FROM t2 AS a1 INTERSECT SELECT 'a'::text AS c0, 1000::bigint AS c1, 100::bigint AS c2;
-- pgfuzz:check kernel:graft_exists WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 5) SELECT '_'::text AS c0, (SELECT COUNT (*) FROM t1 AS a2) AS c1, 0::bigint AS c2 FROM t2 AS a1 INTERSECT SELECT 'a'::text AS c0, 1000::bigint AS c1, 100::bigint AS c2
